<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Camera, ChevronLeft, ChevronRight, Cpu, FolderOpen, HardDrive, Image as ImageIcon, RefreshCw, RotateCcw, RotateCw, Search, Trash2, X } from '@lucide/vue'
import { LocalApi, type VRHardwareStatus, type VRPhoto, type VRPhotoDetail } from './api'

const props=defineProps<{api:LocalApi}>()
const items=ref<VRPhoto[]>([]),total=ref(0),directory=ref(''),query=ref(''),loading=ref(false),message=ref(''),selected=ref<VRPhotoDetail|null>(null),acting=ref(false),hardware=ref<VRHardwareStatus|null>(null),renaming=ref(false),newName=ref('')
const hasMore=computed(()=>items.value.length<total.value)
const grouped=computed(()=>{const groups=new Map<string,VRPhoto[]>();for(const item of items.value){const date=new Date(item.capturedAt||item.modifiedAt);const key=date.toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'});groups.set(key,[...(groups.get(key)||[]),item])}return [...groups.entries()]})
function size(value:number){if(value<1024)return `${value} B`;if(value<1048576)return `${(value/1024).toFixed(1)} KB`;return `${(value/1048576).toFixed(1)} MB`}
function time(value?:string){return value?new Date(value).toLocaleString('zh-CN'):'—'}
async function load(reset=true){loading.value=true;message.value='';try{const result=await props.api.photos(query.value,reset?0:items.value.length,120);directory.value=result.directory;total.value=result.total;items.value=reset?result.items:[...items.value,...result.items];message.value=result.message||''}catch(cause){message.value=cause instanceof Error?cause.message:'无法读取相片'}finally{loading.value=false}}
async function open(item:VRPhoto){try{selected.value=await props.api.photoDetail(item.id);newName.value=selected.value.name}catch(cause){message.value=cause instanceof Error?cause.message:'无法读取相片详情'}}
async function rotate(direction:'left'|'right'){if(!selected.value)return;acting.value=true;try{selected.value=await props.api.rotatePhoto(selected.value.id,direction);replace(selected.value);message.value='方向已调整，原图已保存在 VRC++ 备份目录。'}catch(cause){message.value=cause instanceof Error?cause.message:'无法旋转图片'}finally{acting.value=false}}
async function rename(){if(!selected.value)return;acting.value=true;try{const old=selected.value.id;const result=await props.api.renamePhoto(old,newName.value);items.value=items.value.map(item=>item.id===old?result:item);selected.value=result;renaming.value=false;message.value='文件名已更新。'}catch(cause){message.value=cause instanceof Error?cause.message:'无法重命名'}finally{acting.value=false}}
async function remove(){if(!selected.value||!window.confirm(`删除“${selected.value.name}”？\n照片会移入 VRC++ 回收区，不会立即永久删除。`))return;acting.value=true;try{const id=selected.value.id;const result=await props.api.deletePhoto(id);items.value=items.value.filter(item=>item.id!==id);total.value=Math.max(0,total.value-1);selected.value=null;message.value=result.message}catch(cause){message.value=cause instanceof Error?cause.message:'无法删除相片'}finally{acting.value=false}}
function replace(photo:VRPhoto){items.value=items.value.map(item=>item.id===photo.id?photo:item)}
async function detectHardware(refresh=false){try{hardware.value=await props.api.vrHardware(refresh)}catch{hardware.value=null}}
onMounted(()=>{void load();void detectHardware()})
</script>

<template>
  <section class="photo-library wide-view">
    <article class="photo-hero panel"><div><span class="panel-kicker">VRChat 相片库</span><h2>把头显里的回忆带回桌面</h2><p>自动读取 VRChat 相机保存目录；所有查看和编辑都只在这台电脑上完成。</p></div><div class="photo-summary"><span><ImageIcon :size="18"/><b>{{ total }}</b><small>张相片</small></span><span><HardDrive :size="18"/><b>{{ size(items.reduce((sum,item)=>sum+item.size,0)) }}</b><small>已加载大小</small></span></div></article>
    <article class="hardware-strip panel"><div class="hardware-title"><Cpu :size="19"/><span><strong>头显与运行环境</strong><small>{{ hardware?.message||'正在检测 Windows 设备' }}</small></span></div><div class="hardware-items"><span v-for="device in hardware?.devices" :key="device.deviceId||device.name" class="connected" :title="[device.name,...(device.relatedDevices||[])].join('\n')"><i></i><b>{{ device.family }}</b><small>{{ device.name }}<template v-if="device.relatedDevices?.length"> · {{ device.relatedDevices.length }} 个相关设备</template></small></span><span v-for="runtime in hardware?.runtimes.filter(item=>item.installed)" :key="runtime.name" :class="{running:runtime.running}"><i></i><b>{{ runtime.name }}</b><small>{{ runtime.running?'正在运行':'已安装' }}</small></span><span v-if="!hardware?.devices.length&&!hardware?.runtimes.some(item=>item.installed)" class="empty-device">未识别到设备或 VR 运行环境</span></div><button @click="detectHardware(true)"><RefreshCw :size="15"/>重新检测</button></article>
    <div class="photo-toolbar panel"><label><Search :size="17"/><input v-model="query" placeholder="搜索文件名或日期目录" @keyup.enter="load()"/><button v-if="query" @click="query='';load()"><X :size="14"/></button></label><button @click="load()"><RefreshCw :class="{spin:loading}" :size="16"/>刷新相片</button><span><FolderOpen :size="15"/>{{ directory }}</span></div>
    <p v-if="message" class="photo-message">{{ message }}</p>
    <div v-if="items.length" class="photo-groups"><section v-for="[date,photos] in grouped" :key="date"><header><strong>{{ date }}</strong><span>{{ photos.length }} 张</span></header><div class="photo-grid"><button v-for="photo in photos" :key="photo.id" @click="open(photo)"><img :src="api.photoThumbnailUrl(photo.id,photo.modifiedAt)" loading="lazy"/><span><b>{{ photo.name }}</b><small>{{ photo.width }} × {{ photo.height }} · {{ size(photo.size) }}</small></span></button></div></section></div>
    <article v-else-if="!loading" class="photo-empty panel"><Camera :size="38"/><h3>这里还没有相片</h3><p>{{ message||'用 VRChat 相机拍摄后，照片会自动出现在这里。' }}</p></article>
    <button v-if="hasMore" class="load-more" :disabled="loading" @click="load(false)">{{ loading?'正在加载…':'加载更多相片' }}</button>

    <div v-if="selected" class="photo-overlay" @click.self="selected=null"><article class="photo-detail panel"><header><div><span>相片详情</span><h3>{{ selected.name }}</h3></div><button @click="selected=null"><X :size="19"/></button></header><div class="photo-preview"><img :src="api.photoContentUrl(selected.id,selected.modifiedAt)"/><button class="previous" disabled><ChevronLeft/></button><button class="next" disabled><ChevronRight/></button></div><div class="photo-actions"><button :disabled="acting" @click="rotate('left')"><RotateCcw :size="16"/>左转</button><button :disabled="acting" @click="rotate('right')"><RotateCw :size="16"/>右转</button><button @click="renaming=!renaming"><ImageIcon :size="16"/>重命名</button><button @click="api.revealPhoto(selected.id)"><FolderOpen :size="16"/>所在位置</button><button class="danger" :disabled="acting" @click="remove"><Trash2 :size="16"/>删除</button></div><form v-if="renaming" class="rename-row" @submit.prevent="rename"><input v-model="newName"/><button :disabled="acting">保存</button></form><dl class="photo-metadata"><div><dt>分辨率</dt><dd>{{ selected.width }} × {{ selected.height }}</dd></div><div><dt>画面比例</dt><dd>{{ selected.aspectRatio }}</dd></div><div><dt>像素</dt><dd>{{ selected.megapixels.toFixed(2) }} MP</dd></div><div><dt>格式</dt><dd>{{ selected.extension.toUpperCase() }}</dd></div><div><dt>文件大小</dt><dd>{{ size(selected.size) }}</dd></div><div><dt>拍摄时间</dt><dd>{{ time(selected.capturedAt) }}</dd></div><div><dt>修改时间</dt><dd>{{ time(selected.modifiedAt) }}</dd></div><div class="wide"><dt>完整路径</dt><dd>{{ selected.absolutePath }}</dd></div><div class="wide"><dt>SHA-256</dt><dd class="hash">{{ selected.sha256||'—' }}</dd></div><div v-for="(value,key) in selected.metadata" :key="key" class="wide"><dt>{{ key }}</dt><dd>{{ value }}</dd></div></dl></article></div>
  </section>
</template>

<style scoped>
.photo-library{display:grid;gap:13px}.photo-hero{display:flex;align-items:center;justify-content:space-between;padding:21px}.photo-hero h2{margin:4px 0;font-size:25px}.photo-hero p{margin:0;color:var(--muted);font-size:12px}.photo-summary{display:flex;gap:8px}.photo-summary>span{display:grid;grid-template-columns:auto auto;gap:0 7px;align-items:center;min-width:110px;padding:11px;border:1px solid var(--line);border-radius:10px}.photo-summary svg{grid-row:1/3;color:var(--accent)}.photo-summary b{font-size:17px}.photo-summary small{color:var(--muted);font-size:9px}.hardware-strip{display:flex;align-items:center;gap:12px;padding:12px 15px}.hardware-title{display:flex;align-items:center;gap:8px;min-width:190px}.hardware-title>span,.hardware-title strong,.hardware-title small{display:block}.hardware-title small{margin-top:2px;color:var(--muted);font-size:9px}.hardware-items{display:flex;flex:1;gap:7px;overflow:auto}.hardware-items>span{display:grid;grid-template-columns:auto 1fr;gap:0 6px;min-width:125px;padding:7px 9px;border:1px solid var(--line);border-radius:8px}.hardware-items i{grid-row:1/3;align-self:center;width:7px;height:7px;border-radius:50%;background:#777}.hardware-items .connected i,.hardware-items .running i{background:#4cbf8a}.hardware-items b{font-size:10px}.hardware-items small{color:var(--muted);font-size:8px}.hardware-items .empty-device{display:flex;align-items:center;color:var(--muted)}.hardware-strip>button,.photo-toolbar>button{display:flex;align-items:center;gap:5px;white-space:nowrap}.photo-toolbar{display:grid;grid-template-columns:minmax(220px,420px) auto 1fr;align-items:center;gap:9px;padding:11px}.photo-toolbar label{display:flex;align-items:center;gap:7px;padding:0 10px;border:1px solid var(--line);border-radius:8px}.photo-toolbar input{flex:1;border:0;background:transparent}.photo-toolbar label button{padding:0;border:0;background:transparent}.photo-toolbar>span{display:flex;align-items:center;justify-content:flex-end;gap:5px;overflow:hidden;color:var(--muted);font-size:10px;text-overflow:ellipsis;white-space:nowrap}.photo-message{margin:0;padding:9px 12px;border-radius:8px;background:var(--accent-soft);color:var(--accent);font-size:11px}.photo-groups{display:grid;gap:18px}.photo-groups section>header{display:flex;justify-content:space-between;margin-bottom:8px}.photo-groups header span{color:var(--muted);font-size:10px}.photo-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:9px}.photo-grid button{position:relative;min-width:0;padding:0;overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--surface);color:var(--ink);text-align:left;cursor:pointer}.photo-grid img{display:block;width:100%;aspect-ratio:16/10;object-fit:cover;background:var(--surface-muted)}.photo-grid span{display:block;padding:8px}.photo-grid b,.photo-grid small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.photo-grid b{font-size:10px}.photo-grid small{margin-top:3px;color:var(--muted);font-size:8px}.photo-empty{display:grid;place-items:center;gap:7px;min-height:280px;padding:30px;text-align:center}.photo-empty p{margin:0;color:var(--muted)}.load-more{justify-self:center}.photo-overlay{position:fixed;z-index:110;inset:0;display:grid;place-items:center;padding:24px;background:rgb(0 0 0/.68)}.photo-detail{width:min(1050px,95vw);max-height:92vh;padding:16px;overflow:auto}.photo-detail>header{display:flex;justify-content:space-between;align-items:flex-start}.photo-detail header span{color:var(--accent);font-size:9px}.photo-detail h3{margin:3px 0 10px}.photo-detail header button{border:0;background:transparent}.photo-preview{position:relative;display:grid;place-items:center;min-height:340px;max-height:58vh;overflow:hidden;border-radius:10px;background:#090909}.photo-preview img{max-width:100%;max-height:58vh;object-fit:contain}.photo-preview>button{display:none}.photo-actions{display:flex;flex-wrap:wrap;gap:7px;margin:11px 0}.photo-actions button{display:flex;align-items:center;gap:5px}.photo-actions .danger{margin-left:auto;color:#e46d6d}.rename-row{display:flex;gap:7px;margin-bottom:10px}.rename-row input{flex:1}.photo-metadata{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin:0}.photo-metadata>div{min-width:0;padding:9px;border:1px solid var(--line);border-radius:8px}.photo-metadata .wide{grid-column:span 2}.photo-metadata dt{color:var(--muted);font-size:8px}.photo-metadata dd{margin:4px 0 0;overflow-wrap:anywhere;font-size:10px}.photo-metadata .hash{font-family:monospace;font-size:8px}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@container (max-width:850px){.photo-hero{align-items:flex-start;gap:12px;flex-direction:column}.hardware-strip{align-items:flex-start;flex-wrap:wrap}.hardware-items{order:3;flex-basis:100%}.photo-toolbar{grid-template-columns:1fr auto}.photo-toolbar>span{grid-column:1/3;justify-content:flex-start}.photo-metadata{grid-template-columns:repeat(2,minmax(0,1fr))}.photo-metadata .wide{grid-column:span 2}}
</style>
